import{_ as i,o as e,c as t,ag as a}from"./chunks/framework.ePeAWSvT.js";const k=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/index.md","filePath":"troubleshooting/index.md","lastUpdated":1772297611000}'),n={name:"troubleshooting/index.md"};function l(o,s,r,h,p,c){return e(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>When things are not working as expected, this section helps you diagnose and resolve common issues with NectoProxy. Start with the quick debugging checklist below, then follow the links to detailed troubleshooting pages.</p><h2 id="quick-debugging-checklist" tabindex="-1">Quick Debugging Checklist <a class="header-anchor" href="#quick-debugging-checklist" aria-label="Permalink to &quot;Quick Debugging Checklist&quot;">​</a></h2><p>Run through these checks in order when NectoProxy is not behaving as expected:</p><h3 id="_1-is-nectoproxy-running" tabindex="-1">1. Is NectoProxy Running? <a class="header-anchor" href="#_1-is-nectoproxy-running" aria-label="Permalink to &quot;1. Is NectoProxy Running?&quot;">​</a></h3><p>Verify the proxy process is active:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check if the process is running</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nectoproxy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or try accessing the Web UI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Web UI is reachable&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Web UI is NOT reachable&quot;</span></span></code></pre></div><p>If NectoProxy is not running, start it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="_2-is-your-browser-system-configured-to-use-the-proxy" tabindex="-1">2. Is Your Browser/System Configured to Use the Proxy? <a class="header-anchor" href="#_2-is-your-browser-system-configured-to-use-the-proxy" aria-label="Permalink to &quot;2. Is Your Browser/System Configured to Use the Proxy?&quot;">​</a></h3><p>Check your proxy settings:</p><ul><li><strong>Browser:</strong> Verify the HTTP proxy is set to <code>localhost:8888</code> (or your custom port).</li><li><strong>System:</strong> Check system-level proxy settings if you configured them.</li><li><strong>CLI tools:</strong> Ensure <code>HTTP_PROXY</code> and <code>HTTPS_PROXY</code> environment variables are set if you are using command-line tools.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Test with curl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8888</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://httpbin.org/get</span></span></code></pre></div><h3 id="_3-is-the-ca-certificate-installed" tabindex="-1">3. Is the CA Certificate Installed? <a class="header-anchor" href="#_3-is-the-ca-certificate-installed" aria-label="Permalink to &quot;3. Is the CA Certificate Installed?&quot;">​</a></h3><p>HTTPS traffic requires the NectoProxy CA certificate to be installed and trusted:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Show certificate path and installation instructions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div><p>If you see security errors in your browser for HTTPS sites, the CA certificate is likely not installed. See the <a href="./certificate-errors.html">Certificate Errors</a> page.</p><h3 id="_4-are-you-using-the-correct-port" tabindex="-1">4. Are You Using the Correct Port? <a class="header-anchor" href="#_4-are-you-using-the-correct-port" aria-label="Permalink to &quot;4. Are You Using the Correct Port?&quot;">​</a></h3><p>Verify you are connecting to the right port:</p><ul><li><strong>Proxy port:</strong> Default <code>8888</code> (for browser/system proxy settings)</li><li><strong>Web UI port:</strong> Default <code>8889</code> (for accessing the NectoProxy dashboard)</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check which ports NectoProxy is listening on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8888</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :8889</span></span></code></pre></div><h3 id="_5-is-a-firewall-blocking-connections" tabindex="-1">5. Is a Firewall Blocking Connections? <a class="header-anchor" href="#_5-is-a-firewall-blocking-connections" aria-label="Permalink to &quot;5. Is a Firewall Blocking Connections?&quot;">​</a></h3><p>If connecting from another device (e.g., a phone for mobile debugging):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS: Check if the firewall allows connections</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/libexec/ApplicationFirewall/socketfilterfw</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --getglobalstate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux: Check iptables</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows: Check firewall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> advfirewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name=all</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span></code></pre></div><p>Make sure ports 8888 and 8889 are open for inbound connections if you are using <code>--host 0.0.0.0</code>.</p><h2 id="troubleshooting-pages" tabindex="-1">Troubleshooting Pages <a class="header-anchor" href="#troubleshooting-pages" aria-label="Permalink to &quot;Troubleshooting Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What It Covers</th></tr></thead><tbody><tr><td><a href="./common-issues.html">Common Issues</a></td><td>Frequently encountered problems and their solutions</td></tr><tr><td><a href="./certificate-errors.html">Certificate Errors</a></td><td>SSL/TLS certificate problems and fixes</td></tr><tr><td><a href="./port-conflicts.html">Port Conflicts</a></td><td>EADDRINUSE errors and port management</td></tr><tr><td><a href="./performance.html">Performance</a></td><td>Slow UI, high memory, database growth</td></tr></tbody></table><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you cannot resolve your issue with the information in this section:</p><ol><li><strong>Search existing issues</strong> on the <a href="https://github.com/sitharaj88/nectoproxy/issues" target="_blank" rel="noreferrer">NectoProxy GitHub Issues</a> page.</li><li><strong>Open a new issue</strong> with: <ul><li>Your operating system and version</li><li>Node.js version (<code>node -v</code>)</li><li>NectoProxy version (<code>nectoproxy --version</code>)</li><li>Steps to reproduce the problem</li><li>Any error messages from the terminal</li><li>Browser name and version (if relevant)</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When reporting issues, include the terminal output from NectoProxy&#39;s startup. This often contains error messages that help diagnose the problem quickly.</p></div>`,31)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
